const items = $input.all();

// Items from merge: first batch = tickets, after that = stats
const allData = items.map(i => i.json);

// Find stats item (has 'total' key)
const statsItem = allData.find(d => d.total !== undefined) || {};

// Tickets are all items that are NOT the stats
const tickets = allData.filter(d => d.ticket_id !== undefined);

return [{
  json: {
    stats: {
      total: parseInt(statsItem.total) || 0,
      recibidos: parseInt(statsItem.recibidos) || 0,
      escalados: parseInt(statsItem.escalados) || 0,
      resueltos_auto: parseInt(statsItem.resueltos_auto) || 0,
      cerrados_humano: parseInt(statsItem.cerrados_humano) || 0,
      criticos: parseInt(statsItem.criticos) || 0,
      simples: parseInt(statsItem.simples) || 0,
      ultimos_7_dias: parseInt(statsItem.ultimos_7_dias) || 0
    },
    tickets: tickets.map(t => ({
      ticket_id: t.ticket_id,
      email: t.email,
      subject: t.subject,
      categoria: t.categoria,
      sentimiento: t.sentimiento,
      complejidad: t.complejidad,
      lenguaje_agresivo: t.lenguaje_agresivo,
      estado: t.estado,
      received_at: t.received_at,
      created_at: t.created_at,
      updated_at: t.updated_at,
      historial: t.historial || []
    })),
    generated_at: new Date().toISOString()
  }
}];
